import {
	CSS_RUNTIME_METHODS,
	normalizeCssRuntimeMethods,
	renderCssRuntimeModule,
	type CssRuntimeMethod,
} from "yumcss/_runtime/css-codegen";

export const RUNTIME_CSS_GENERATED_HEADER =
	"// Generated by yumcss-codemod runtime generate; do not edit.";

export const DEFAULT_RUNTIME_CSS_OUTPUT = "src/yumcss-runtime.ts";

/** Parse the CLI method vocabulary into a stable attachment selection. */
export const parseRuntimeMethods = (specification = "all"): CssRuntimeMethod[] => {
	const specificationValue = specification.trim();
	if (specificationValue === "all") return [...CSS_RUNTIME_METHODS];
	if (specificationValue === "call") return [];
	if (specificationValue.length === 0)
		throw new Error("runtime generate: --methods must name methods, 'call', or 'all'");
	const methods = specificationValue.split(",").map((method) => method.trim());
	if (methods.some((method) => method.length === 0))
		throw new Error("runtime generate: --methods contains an empty method name");
	if (methods.some((method) => method === "call"))
		throw new Error("runtime generate: 'call' cannot be combined with named methods");
	return normalizeCssRuntimeMethods(methods);
};

/** Render the checked-in-project module emitted by `runtime generate`. */
export const generateRuntimeCssModule = (
	methods: readonly CssRuntimeMethod[] = CSS_RUNTIME_METHODS,
): string => `${RUNTIME_CSS_GENERATED_HEADER}\n${renderCssRuntimeModule(methods, { typed: true })}`;

export const runtimeMethodSummary = (methods: readonly CssRuntimeMethod[]): string =>
	methods.length === 0 ? "callable core" : methods.join(", ");
